def most_common(lst):
    """
    Повертає найчастіший елемент у списку.
    Якщо декілька елементів мають однакову найвищу частоту,
    повертається будь-який з них.
    """
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    max_count = max(counts.values())
    for item, count in counts.items():
        if count == max_count:
            return item
```

